import { useCallback, useMemo, useState } from "react";
import { ALL_SELECT_OPTION_ID, getFiltersSearchTypeAllOption } from "./components/filtersSelect";
import { useDebouncedMemo } from "../commonHelpers/hooks/useDebouncedMemo";
export const useFiltersSearch = (keywordDebounceTime = 300) => {
    const [keyword, setKeyword] = useState("");
    const [searchType, setSearchType] = useState(getFiltersSearchTypeAllOption());
    const isTypeEnabled = useCallback((type) => Object.keys(searchType).includes(ALL_SELECT_OPTION_ID) || Object.keys(searchType).includes(type), [searchType]);
    const debouncedKeyword = useDebouncedMemo(() => keyword, [keyword], keywordDebounceTime);
    return { keyword, setKeyword, searchType, setSearchType, isTypeEnabled, debouncedKeyword };
};
export const usePinnedFilters = () => {
    const [isPinned, setIsPinned] = useState(false);
    const pinnedFilters = useMemo(() => ({ isPinned, onPinChange: setIsPinned }), [isPinned, setIsPinned]);
    return pinnedFilters;
};
export const useFiltersSelection = () => {
    const [searchSelection, setSearchSelection] = useState([]);
    return { searchSelection, setSearchSelection };
};
